from checked_integer import *
from ail import open_binary, same_file
# Bounded data buffers; the destination may contain a prefix after an I/O error.
def binary_stream_copy(input_path: str, output_path: str, chunk_size: int) -> int:
    if chunk_size <= 0:
        raise ValueError
    if same_file(input_path, output_path):
        raise OSError
    source = open_binary(input_path, 'r')
    try:
        target = open_binary(output_path, 'w')
        try:
            buffer = bytearray(chunk_size)
            total: int = 0
            while True:
                count = source.readinto(buffer)
                if count == 0:
                    break
                target.write(buffer[:count])
                total = checked_int64_add(total, count)
            target.flush()
            return total
        finally:
            target.close()
    finally:
        source.close()
